---定时器回调
function JapaneseStoryChapterNode:TimerHandler()
    local data = self:GetData()
    if JapaneseStoryMgr:CheckChapterOpenTime(data.unlockCountdown) then return end

    local text = string.format(localize("距离开放：_num_", {_num_ = CfUtils.GetTimeHMS10(checkInt(data.unlockCountdown + JapaneseStoryMgr:GetEnterTimestamp() - GameUtils.GetServerTime()))}))
    CfUtils.FillText(self.LockTxt, text)
end
