--region public
---刷新node
function JapaneseStoryChapterNode:RefreshNode(data, index, cb)
    self:SetData(data)
    self:SetIndex(index)
    self:SetCB(cb)
    
    local vo = JapaneseStoryMgr:GetChapterVoById(data.questId)
    CfUtils.SetUISwitchImage(self.ImgFan, index)
    -- 表里没配，先写死
    CfUtils.FillImage(self.ImgBg, string.format('Arts/Textures/ActivityJapaneseLevel/Entry/activity_hefeng_img_inner%d_1.png', self._index))
    CfUtils.FillImage(self.ImgIcon, string.format('Arts/Textures/ActivityJapaneseLevel/Entry/activity_hefeng_img_inner%d_2.png', self._index))
    CfUtils.FillImage(self.ImgFlower, string.format('Arts/Textures/ActivityJapaneseLevel/Entry/activity_hefeng_img_chapter%d_dec.png', self._index))
    CfUtils.FillImage(self.LockImgFlower, string.format('Arts/Textures/ActivityJapaneseLevel/Entry/activity_hefeng_img_chapter%d_dec.png', self._index))

    if not JapaneseStoryMgr:CheckChapterOpenTime(data.unlockCountdown) then
        -- 日期锁定
        CfUtils.SetActive(self.UIFX_Glow, false)
        CfUtils.SetActive(self.ImgBgTitle, false)
        CfUtils.SetActive(self.Lock, true)
        CfUtils.SetActive(self.ImgGet, false)
        CfUtils.SetActive(self.LockTxt, true)
        CfUtils.SetActive(self.LockImgBgTitle, true)
        local text = string.format(localize("距离开放：_num_", {_num_ = CfUtils.GetTimeHMS10(checkInt(data.unlockCountdown + JapaneseStoryMgr:GetEnterTimestamp() - GameUtils.GetServerTime()))}))
        CfUtils.FillText(self.LockTxt, text)
        self:StartTimer()
        return
    end

    CfUtils.SetActive(self.ImgBgTitle, true)
    CfUtils.SetUISwitchText(self.ImgBgTitleTxt, 1)
    CfUtils.FillText(self.ImgBgTitleTxt, vo.name)
    -- 0未解锁 1已解锁 2已通关
    local status = checkInt(data.status)
    if status == 0 then
        CfUtils.SetActive(self.UIFX_Glow, false)
        CfUtils.SetActive(self.LockImgBgTitle, false)
        CfUtils.SetActive(self.Lock, true)
        CfUtils.SetActive(self.ImgGet, false)
        CfUtils.SetActive(self.LockTxt, false)
        CfUtils.SetActive(self.ImgFlower, false)
    elseif status == 1 then
        CfUtils.SetActive(self.UIFX_Glow, true)
        CfUtils.SetActive(self.Lock, false)
        CfUtils.SetActive(self.ImgGet, false)
        CfUtils.SetActive(self.ImgFlower, true)
    elseif status == 2 then
        CfUtils.SetActive(self.UIFX_Glow, false)
        CfUtils.SetActive(self.Lock, false)
        CfUtils.SetActive(self.ImgGet, true)
        CfUtils.SetActive(self.ImgFlower, true)
    end
end
--endregion public

